&reftitle.description;
boolftp_fget FTP\Connectionftp resourcestream stringremote_filename intmodeFTP_BINARY intoffset0
ftp_fget recupera remote_filename dal server FTP e lo scrive nel puntatore al file indicato.

&reftitle.changelog;





    &Version;
    &Description;



   &ftp.changelog.ftp-param;
   &ext.ftp.changelog.mode-valueerror;


    7.3.0

     Il parametro mode ora è opzionale. In precedenza
     era obbligatorio.

  &reftitle.examples;



    Esempio di ftp_fget


<?php

// percorso del file remoto
$remote_file = 'somefile.txt';
$local_file = 'localfile.txt';

// apre un file in cui scrivere
$handle = fopen($local_file, 'w');

// stabilisce la connessione di base
$ftp = ftp_connect($ftp_server);

// si collega con nome utente e password
$login_result = ftp_login($ftp, $ftp_user_name, $ftp_user_pass);

// tenta di scaricare $remote_file e di salvarlo in $handle
if (ftp_fget($ftp, $handle, $remote_file, FTP_ASCII, 0)) {
 echo "scritto correttamente in $local_file\n";
} else {
 echo "Si è verificato un problema durante lo scaricamento di $remote_file in $local_file\n";
}

// chiude la connessione e l'handle del file
ftp_close($ftp);
fclose($handle);
?>
